// Official logos of the resources linked by the widgets, inlined since the widget CSP blocks external images
import { Show } from "solid-js";

const NCBI_LOGO =
  "data:image/svg+xml;base64,";

/** Logo of each resource, `wordmark` when it shows the resource name, `height` in px to even out their margins */
const LOGOS: Record<string, { src: string; wordmark?: boolean; height?: number }> = {
  "BRC Analytics": {
    wordmark: true,
    src: "data:image/svg+xml;base64,",
  },
  STRING: {
    wordmark: true,
    src: "data:image/png;base64,",
  },
  UniProt: {
    wordmark: true,
    height: 20,
    src: "data:image/svg+xml;base64,",
  },
  Ensembl: {
    wordmark: true,
    height: 11,
    src: "data:image/svg+xml;base64,",
  },
  HGNC: {
    wordmark: true,
    height: 18,
    src: "data:image/svg+xml;base64,",
  },
  MGI: {
    wordmark: true,
    height: 20,
    src: "data:image/gif;base64,",
  },
  gnomAD: {
    wordmark: true,
    height: 17,
    src: "data:image/svg+xml;base64,",
  },
  MyVariant: {
    src: "data:image/png;base64,",
  },
  Entrez: { src: NCBI_LOGO },
  GEO: { src: NCBI_LOGO },
  dbSNP: { src: NCBI_LOGO },
  ClinVar: { src: NCBI_LOGO },
};

/** Content of a link to a resource: its logo, followed by its name when the logo does not show it */
export function Logo(props: { name: string }) {
  const logo = () => LOGOS[props.name];
  return (
    <Show when={logo()} fallback={props.name}>
      {(logo) => (
        <>
          <img
            src={logo().src}
            alt={logo().wordmark ? props.name : ""}
            style={logo().height ? { height: `${logo().height}px` } : undefined}
          />
          {logo().wordmark ? "" : props.name}
        </>
      )}
    </Show>
  );
}
